// Synthetic ESM package that uses globals only (spec question 4). data: URLs keep the
// check offline.
export async function get() {
  const res = await fetch("data:text/plain,hello");
  return res.text();
}
export function token() {
  return process.env.SPIKE_TOKEN ?? null;
}
export function later() {
  // Attribution from inside a timer callback: the callback is still this file's code.
  return new Promise((resolve) => setTimeout(() => resolve(fetch("data:text/plain,later").then((r) => r.text())), 1));
}
